import os
import json
from mem0 import Memory

def main():
    run_id = os.environ.get("ZEALT_RUN_ID", "default_run")
    collection_name = f"mem0_demo_{run_id}"
    print(f"Run ID: {run_id}")
    print(f"Collection: {collection_name}")

    config = {
        "vector_store": {
            "provider": "chroma",
            "config": {
                "collection_name": collection_name,
                "path": "/home/user/myproject/chroma_db"
            }
        }
    }

    m = Memory.from_config(config)
    print("Memory initialized successfully")

    # Let's add a conversation
    messages = [
        {"role": "user", "content": "Hi, I'm Alex. I am a vegan and I really enjoy hiking on weekends."},
        {"role": "assistant", "content": "Hello Alex! It's great to meet you. I've noted that you are a vegan and love weekend hiking."}
    ]

    res = m.add(
        messages=messages,
        user_id="alex",
        metadata={"category": "preferences"}
    )
    print("Add response:")
    print(json.dumps(res, indent=2))

if __name__ == "__main__":
    main()

